<div x-show="order.length"><h2 class="text-lg font-semibold mb-3 flex items-center gap-2"><x-capstone::badge variant="secondary" class="bg-green-100 text-green-800">Bid</x-capstone::badge>Judul yang Anda Bidding</h2><div class="grid gap-4"><template x-for="(bid,index) in order" :key="bid.id"><x-capstone::card class="relative" ::class="bid.lecturer_recommendation==='ACCEPT' && 'border-green-300 bg-green-50/30'"><div class="px-6 pb-3 flex flex-wrap justify-between items-start gap-3"><div class="flex items-center gap-3"><div x-show="isLeader" class="flex flex-col gap-1"><x-capstone::button variant="ghost" size="sm" class="h-6 w-6 p-0" aria-label="Move priority up" @click="move(index,-1)" ::disabled="!index || !canReorder || saving"><x-capstone::icon name="ArrowUp" class="h-3 w-3" /></x-capstone::button><x-capstone::button variant="ghost" size="sm" class="h-6 w-6 p-0" aria-label="Move priority down" @click="move(index,1)" ::disabled="index===order.length-1 || !canReorder || saving"><x-capstone::icon name="ArrowDown" class="h-3 w-3" /></x-capstone::button></div><div class="h-10 w-10 shrink-0 rounded-full flex items-center justify-center font-bold text-lg" :class="bid.lecturer_recommendation==='ACCEPT'?'bg-green-600 text-white':'bg-green-100 text-green-700'" x-text="bid.priority"></div><div><h3 class="font-semibold text-base" x-text="bid.title?.title"></h3><p class="text-sm text-muted-foreground">Lecturer: <span x-text="person(bid.title?.lecturer)"></span></p></div></div><div class="flex items-center gap-2"><x-capstone::badge variant="outline" ::class="badge(bid.status)" x-text="bid.status" /><x-capstone::badge x-show="bid.lecturer_recommendation==='ACCEPT'">DITERIMA</x-capstone::badge><x-capstone::badge variant="destructive" x-show="bid.status==='REJECTED'">DITOLAK</x-capstone::badge></div></div><div class="px-6 border-t pt-3 flex justify-between items-center"><span class="text-sm text-muted-foreground">Priority #<span x-text="bid.priority"></span></span><x-capstone::button variant="ghost" size="sm" class="text-destructive" x-show="bid.status==='PENDING' && canDelete" @click="remove(bid)" ::disabled="saving"><x-capstone::icon name="Trash2" />Delete</x-capstone::button></div></x-capstone::card></template></div></div><div x-show="rejected.length" class="mt-6"><h2 class="text-lg font-semibold mb-1 flex items-center gap-2"><x-capstone::badge variant="destructive">Riwayat</x-capstone::badge>Bid Ditolak Dosen</h2><p class="text-sm text-muted-foreground mb-3">Bid berikut ditolak dan otomatis dikeluarkan dari slot aktif &mdash; slot Anda sudah dibebaskan untuk bid judul lain.</p><div class="grid gap-4"><template x-for="bid in rejected" :key="bid.id"><x-capstone::card class="relative border-destructive/40 bg-muted/20"><div class="px-6 pb-3 flex flex-wrap justify-between items-start gap-3"><div><h3 class="font-semibold text-base" x-text="bid.title?.title"></h3><p class="text-sm text-muted-foreground">Lecturer: <span x-text="person(bid.title?.lecturer)"></span></p></div><div class="flex items-center gap-2"><x-capstone::badge variant="outline" ::class="badge(bid.status)" x-text="bid.status" /><x-capstone::badge variant="destructive">DITOLAK</x-capstone::badge></div></div><div class="px-6 border-t pt-3 flex justify-between items-center"><span class="text-sm text-muted-foreground">Ditolak dosen &mdash; tidak memakan slot</span><x-capstone::button variant="ghost" size="sm" class="text-destructive" x-show="canDelete" @click="remove(bid)" ::disabled="saving"><x-capstone::icon name="Trash2" />Hapus riwayat</x-capstone::button></div></x-capstone::card></template></div></div>
